using System.Collections.Frozen;

namespace RfaFormats.Guerrilla;

/// <summary>
/// Anchor data of ours for the destructible objects whose saved anchor data Guerrilla's zones left stale. As an
/// object streams in, both games compare its zone's dest_checksum with its chunk file's: the same, and they
/// trust its saved world_anchors (the pieces held to the ground) and dynamic_links (its links to other
/// objects); different, and they throw them away and find them by contact (Havok's getPenetrations hands
/// each touching piece to subpiece_collector::set_as_anchor), Armageddon then showing "Zone 0x... has out of
/// date anchor data, resave the zone ..." on screen. Guerrilla's 0105smokestack_a towers in terr01_04_10 carry
/// data saved for an older version of their file (zone checksum B38896DE, the file's D5E8ED3C): their anchors
/// name pieces up to 50 m up the stack. So for them the builder writes what the game itself works out by
/// contact in our world (captured from its own run, 2026-11-11, by guerrilla_world's "Contact:" log), with the
/// file's own checksum: the zone "resaved", the game trusting it and showing nothing, and the towers held at
/// their base and linked to their rings exactly as the game would hold and link them. It is used only where
/// the zone's and the file's checksums are the ones it was made for; any other stale object keeps Guerrilla's
/// data (and the game finds its anchors itself, and warns).
/// </summary>
public static class GuerrillaAnchorFixes
{
    /// <summary>A link the game made: object A's piece, object B's piece, their depths from the ground, the contact area (m² × 1024).</summary>
    public readonly record struct Link(uint A, ushort PieceA, uint B, ushort PieceB, ushort DepthA, ushort DepthB, int Area);

    /// <summary>One chunk file's corrected data: the checksums it is for, each object's pieces held to the ground (by its handle in Guerrilla's zone), and the links between them, in the order the game made them.</summary>
    public sealed record Fix(string Chunk, uint FileChecksum, uint StaleChecksum, FrozenDictionary<uint, ushort[]> Anchors, Link[] Links);

    /// <summary>The fix for an object of this chunk file with this zone checksum, if the file is the one it was made for and it has the object (by its handle in Guerrilla's zone).</summary>
    public static Fix? For(string chunk, uint zoneChecksum, uint fileChecksum, uint handle) =>
        Fixes.FirstOrDefault(f => f.Chunk.Equals(chunk, StringComparison.OrdinalIgnoreCase) && f.StaleChecksum == zoneChecksum && f.FileChecksum == fileChecksum &&
                                  (f.Anchors.ContainsKey(handle) || f.Links.Any(l => l.A == handle || l.B == handle)));

    static Link L(uint a, ushort pieceA, uint b, ushort pieceB, ushort depthA, ushort depthB, int area) => new(a, pieceA, b, pieceB, depthA, depthB, area);

